'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nanf' );
var isInfinite = require( '@stdlib/math/base/assert/is-infinitef' );
var pow = require( '@stdlib/math/base/special/powf' );
var floor = require( '@stdlib/math/base/special/floorf' );
var ceil = require( '@stdlib/math/base/special/ceilf' );
var log10 = require( '@stdlib/math/base/special/log10f' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var MAX_EXP = require( '@stdlib/constants/float32/max-base10-exponent' );
var MIN_EXP_SUBNORMAL = require( '@stdlib/constants/float32/min-base10-exponent-subnormal' );
var PINF = require( '@stdlib/constants/float32/pinf' );


// MAIN //

/**
* Rounds a single-precision floating-point number to the nearest power of `10` toward positive infinity.
*
* @param {number} x - input value
* @returns {number} rounded value
*
* @example
* var v = ceil10f( 3.141592653589793 );
* // returns 10.0
*
* @example
* var v = ceil10f( 9.0 );
* // returns 10.0
*
* @example
* var v = ceil10f( -0.314 );
* // returns ~-0.1
*/
function ceil10f(x) {
	var sign;
	var p;

	x = float64ToFloat32(x);
	if (
		isnan(x) ||
		isInfinite(x) ||
		x === 0.0
	) {
		return x;
	}
	if (x < 0.0) {
		x = -x;
		sign = -1.0;
	} else {
		sign = 1.0;
	}
	// Solve the equation `10^p = x` for `p`:
	p = log10(x);

	// Determine a power of 10 which rounds the input value toward positive infinity:
	if (sign === -1.0) {
		p = floor(p);
	} else {
		p = ceil(p);
	}
	// Handle underflow:
	if (p <= MIN_EXP_SUBNORMAL) {
		return float64ToFloat32(sign * 0.0); // sign-preserving
	}
	// Handle overflow:
	if (p > MAX_EXP) {
		return float64ToFloat32(sign * PINF);
	}
	return float64ToFloat32(sign * pow(10.0, p));
}


// EXPORTS //

module.exports = ceil10f;
